class Solution {
public:
    bool wordBreak(string s, vector<string>& wordDict) {
        // 算法思路：动态规划。dp[i] 表示 s 的前 i 个字符能否由字典单词拼接，
        // 转移时枚举最后一段的起点 j，要求 dp[j] 为真且子串在字典中。
        // 关键点：字典转 unordered_set 加速查找；用 max_len 剪枝枚举范围。
        // 易错点：dp[0] 必须初始化为 true，表示空前缀可拼接。
        // 时间复杂度 O(n*max_len)，空间复杂度 O(n)。
        unordered_set<string> words(wordDict.begin(), wordDict.end());
        int max_len = 0;
        for (const string& w : words) max_len = max(max_len, (int)w.size());
        int n = (int)s.size();
        vector<bool> dp(n + 1, false);
        dp[0] = true;
        for (int i = 1; i <= n; i++) {
            for (int j = max(0, i - max_len); j < i; j++) {
                if (dp[j] && words.count(s.substr(j, i - j))) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[n];
    }
};

