    // 则剩余数自然构成另一半，即可等和分割。
    // 关键点：总和为奇数直接输出 false；内层循环倒序遍历保证每个数只用一次。
    // 易错点：空数组总和为 0 时按 LeetCode 语义应输出 true。
    // 时间复杂度 O(n * target)，空间复杂度 O(target)。
    int n;
    cin >> n;
    vector<int> nums(n);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        cin >> nums[i];
        total += nums[i];
    }
    if (total % 2 == 1) {
        cout << "false\n";
        return 0;
    }
    int target = (int)(total / 2);
    vector<bool> dp(target + 1, false);
    dp[0] = true;
    for (int v : nums) {
        for (int s = target; s >= v; s--) {
            if (dp[s - v]) dp[s] = true;
        }
    }
    cout << (dp[target] ? "true" : "false") << '\n';
    return 0;
}
